// app/api/backtest/route.ts
import { createClient } from '@supabase/supabase-js'
import { getEnv } from '@/lib/env'
import { apiError } from '@/lib/routeGuard'
import { checkRateLimit, rateLimited } from '@/lib/rateLimit'
import {
  runBacktest, summarize, DEFAULT_PARAMS,
  type Bar, type BarsByTF, type BacktestParams,
} from '@jack-trade/engine'
import type { TwelveDataBar } from '@jack-trade/shared'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co'
const supabaseKey = process.env.SUPABASE_SERVICE_KEY || 'placeholder-service-key'
const supabase = createClient(supabaseUrl, supabaseKey)

const TD_KEY = process.env.TWELVEDATA_API_KEY
const DAILY_LIMIT = 800

function todayUTC() {
  return new Date().toISOString().slice(0, 10)
}
async function getUsage(): Promise<number> {
  const { data } = await supabase.from('av_usage').select('count').eq('usage_date', todayUTC()).maybeSingle()
  return data?.count ?? 0
}
async function incrementUsage(by: number): Promise<number> {
  const next = (await getUsage()) + by
  await supabase.from('av_usage').upsert({ usage_date: todayUTC(), count: next })
  return next
}

async function fetchSeriesPaginated(
  interval: string, startDate: string, endDate: string
): Promise<{ bars: Bar[]; creditsUsed: number }> {
  const allBars: Bar[] = []
  let cursor = endDate
  let creditsUsed = 0
  const startTime = new Date(startDate).getTime()

  for (let guard = 0; guard < 40; guard++) {
    const url = `https://api.twelvedata.com/time_series?symbol=XAU/USD&interval=${interval}&end_date=${encodeURIComponent(cursor)}&order=DESC&outputsize=5000&apikey=${TD_KEY}`
    const res = await fetch(url)
    const data = await res.json()
    creditsUsed++

    if (data?.status === 'error' || !Array.isArray(data?.values) || data.values.length === 0) break

    const chunk: Bar[] = (data.values as TwelveDataBar[]).map((v) => ({
      time: String(v.datetime).replace(' ', 'T') + 'Z',
      open: parseFloat(String(v.open)), high: parseFloat(String(v.high)), low: parseFloat(String(v.low)), close: parseFloat(String(v.close)),
    }))
    allBars.push(...chunk)

    const oldest = chunk[chunk.length - 1]
    if (new Date(oldest.time).getTime() <= startTime) break
    if (chunk.length < 5000) break

    cursor = new Date(new Date(oldest.time).getTime() - 1000).toISOString().slice(0, 19).replace('T', ' ')
  }

  const bars = allBars
    .filter(b => new Date(b.time).getTime() >= startTime)
    .sort((a, b) => a.time.localeCompare(b.time))

  return { bars, creditsUsed }
}

// STAGE SYNC: fetchDxy() removed entirely. DXY no longer gates any
// signal type as of BRUVV Stage 36 (confirmed by direct comparison
// against a reference script -- Setup A, Setup B, and Precision all
// dropped their DXY-agreement requirement). Fetching it here was
// spending 1 real Twelve Data credit per backtest run on data the
// engine never used for anything -- pure waste, removed at the
// source rather than left as unused dead weight.

function monthlyToYearly(monthly: Bar[]): Bar[] {
  const byYear = new Map<string, Bar[]>()
  for (const bar of monthly) {
    const year = bar.time.slice(0, 4)
    if (!byYear.has(year)) byYear.set(year, [])
    byYear.get(year)!.push(bar)
  }
  const out: Bar[] = []
  for (const [year, bars] of Array.from(byYear.entries()).sort()) {
    out.push({
      time: `${year}-01-01T00:00:00Z`,
      open: bars[0].open,
      high: Math.max(...bars.map(b => b.high)),
      low: Math.min(...bars.map(b => b.low)),
      close: bars[bars.length - 1].close,
    })
  }
  return out
}

function mergeParams(overrides: Partial<BacktestParams>): BacktestParams {
  return { ...DEFAULT_PARAMS, ...overrides }
}

export async function POST(req: Request) {
  // Phase 1 (R1, interim): browser-called, so no machine secret possible yet
  // (Phase 3's same-origin proxy takes over). Until then: kill switch +
  // per-IP daily cap so one visitor can't drain the Twelve Data quota.
  if (getEnv().BACKTEST_ENABLED === 'false') {
    return apiError('disabled', 'Backtesting is disabled (BACKTEST_ENABLED=false).', 403);
  }
  const limited = checkRateLimit(req, 'backtest', 10, 86400);
  if (limited !== null) return rateLimited(limited);
  if (!TD_KEY || TD_KEY.includes('paste_your')) {
    return Response.json({ error: 'Twelve Data API key not set (TWELVEDATA_API_KEY).' })
  }

  const body = await req.json()
  const startDate: string = body.startDate
  const endDate: string = body.endDate
  const configs: { name: string; params: Partial<BacktestParams> }[] = body.configs?.length
    ? body.configs
    : [{ name: 'Baseline (current live settings)', params: {} }]

  if (!startDate || !endDate) {
    return Response.json({ error: 'startDate and endDate are required.' })
  }
  if (configs.length > 4) {
    return Response.json({ error: 'Maximum 4 configurations per run, to keep this within a reasonable quota footprint.' })
  }

  const used = await getUsage()
  if (used >= DAILY_LIMIT) {
    return Response.json({ error: `Daily Twelve Data limit reached (${used}/${DAILY_LIMIT}). Resets at 00:00 UTC.`, quotaExceeded: true })
  }

  try {
    let creditsUsed = 0

    // STAGE SYNC: dxy removed from this Promise.all -- 8 series now,
    // not 9. One fewer credit spent per run than before, for free.
    const [oneMin, fiveMin, fifteenMin, sixtyMin, fourHour, daily, weekly, monthly] = await Promise.all([
      fetchSeriesPaginated('1min', startDate, endDate),
      fetchSeriesPaginated('5min', startDate, endDate),
      fetchSeriesPaginated('15min', startDate, endDate),
      fetchSeriesPaginated('1h', startDate, endDate),
      fetchSeriesPaginated('4h', startDate, endDate),
      fetchSeriesPaginated('1day', startDate, endDate),
      fetchSeriesPaginated('1week', startDate, endDate),
      fetchSeriesPaginated('1month', startDate, endDate),
    ])

    creditsUsed = [oneMin, fiveMin, fifteenMin, sixtyMin, fourHour, daily, weekly, monthly]
      .reduce((sum, r) => sum + r.creditsUsed, 0)

    if (oneMin.bars.length === 0) {
      return Response.json({ error: 'No 1-minute price data returned for this date range -- try a shorter or more recent range.' })
    }

    const barsByTF: BarsByTF = {
      '1': oneMin.bars,
      '3': fiveMin.bars,
      '5': fiveMin.bars,
      '15': fifteenMin.bars,
      '60': sixtyMin.bars,
      '240': fourHour.bars,
      'D': daily.bars,
      'W': weekly.bars,
      'M': monthly.bars,
      '12M': monthlyToYearly(monthly.bars),
    }

    await incrementUsage(creditsUsed)

    const results = configs.map(cfg => {
      const params = mergeParams(cfg.params)
      const { signals, diagnostics } = runBacktest(barsByTF, params)
      return { name: cfg.name, params, summary: summarize(signals), signals, diagnostics }
    })

    return Response.json({
      results,
      meta: {
        barsCounts: {
          '1m': oneMin.bars.length, '5m': fiveMin.bars.length, '15m': fifteenMin.bars.length,
          '1h': sixtyMin.bars.length, '4h': fourHour.bars.length, 'D': daily.bars.length,
          'W': weekly.bars.length, 'M': monthly.bars.length,
        },
        // STAGE ADD: real diagnostic -- '1m 5000' alone doesn't tell
        // us whether that 5000 genuinely spans the full requested
        // range, or whether pagination silently stopped after one
        // page and only covers a recent sub-window. This shows the
        // actual earliest/latest timestamp fetched, directly
        // answerable instead of inferred from a bar count alone.
        oneMinuteRangeActuallyFetched: oneMin.bars.length > 0
          ? { earliest: oneMin.bars[0].time, latest: oneMin.bars[oneMin.bars.length - 1].time }
          : null,
        creditsUsed,
        used: used + creditsUsed,
        limit: DAILY_LIMIT,
      },
    })
  } catch (err: unknown) {
    return Response.json({ error: err instanceof Error ? err.message : 'Backtest run failed.' })
  }
}